}
func loadExtraction(entry cacheEntry,key string)(extractionRecord,bool){
 file,err:=entry.open();if err!=nil{return extractionRecord{},false};defer file.Close()
 zip,err:=gzip.NewReader(file);if err!=nil{return extractionRecord{},false};defer zip.Close()
 data,err:=io.ReadAll(io.LimitReader(zip,extractionDecodeLimit+1));if err!=nil||len(data)>extractionDecodeLimit{return extractionRecord{},false}
