}
var extractionMaintenance sync.Mutex

// Maintenance follows held directory capabilities, and removes only internally
// named regular entries. Admission fails closed when bounded scanning is exceeded.
func maintainExtractionCache(entry cacheEntry,incoming int64) bool {
 if os.MkdirAll(entry.root,0700)!=nil{return false}
 root,err:=os.OpenRoot(entry.root);if err!=nil{return false};defer root.Close()
 dir,err:=openCacheDirectory(root,filepath.Dir(entry.relative));if err!=nil{return false};defer dir.Close()
 file,err:=dir.Open(".");if err!=nil{return false};defer file.Close()
 entries,err:=file.ReadDir(extractionEntryLimit+1);if err!=nil&&err!=io.EOF{return false}
 if len(entries)>extractionEntryLimit{return false}
 type item struct{name string; size int64; modified int64}
 var items []item;var total int64
 for _,entry:=range entries {
  name:=entry.Name();if !strings.HasSuffix(name,".json.gz")||!validSHA256Hex(strings.TrimSuffix(name,".json.gz")){continue}
  info,err:=dir.Lstat(name);if err!=nil||!info.Mode().IsRegular(){continue}
  items=append(items,item{name,info.Size(),info.ModTime().UnixNano()});total+=info.Size()
 }
 sort.Slice(items,func(i,j int)bool{if items[i].modified!=items[j].modified{return items[i].modified<items[j].modified};return items[i].name<items[j].name})
 remaining:=len(items)
 for _,item:=range items {
  if total+incoming<=extractionDiskLimit&&remaining<extractionEntryLimit{break}
  if dir.Remove(item.name)!=nil{return false};total-=item.size;remaining--
 }
