// rerankSearchCandidates applies only to the existing candidate pool. A global
// exact-match fallback preserves the entire current exact-query ordering, not
// just its top result. Deep sparse fusion requires its own evaluation arm.
func rerankSearchCandidates(ctx context.Context,candidates []searchCandidate,relations []RelationRecord,deep bool)(graphRankDiagnostics,error){
 diagnostics:=graphRankDiagnostics{}
 if deep{diagnostics.Fallback="deep_fusion_not_evaluated";return diagnostics,nil}
 lexical:=map[string]float64{}
 keys:=make([]string,len(candidates));maximum:=0.0
 for i,candidate:=range candidates{
  if searchResultHasSignal(candidate.result,"exact-symbol")||searchResultHasSignal(candidate.result,"exact-code-token"){diagnostics.Fallback="exact_match_preserved";return diagnostics,nil}
  if candidate.score<0||math.IsNaN(candidate.score)||math.IsInf(candidate.score,0){diagnostics.Fallback="nonpositive_or_invalid_lexical_score";return diagnostics,nil}
  key:=candidate.result.SymbolID
  if key==""{key="rank-region:"+extractionIdentity(candidate.result.FilePath,strconv.Itoa(candidate.result.StartLine),strconv.Itoa(candidate.result.EndLine))}
  keys[i]=key;lexical[key]=math.Max(lexical[key],candidate.score);maximum=math.Max(maximum,candidate.score)
 }
 scores,diagnostics,err:=graphRankScores(ctx,lexical,relations);if err!=nil||diagnostics.Fallback!=""{return diagnostics,err}
 for i:=range candidates{
  graphComponent:=(scores[keys[i]]-.8*lexical[keys[i]]/maximum)/.2
  lexicalComponent:=candidates[i].score/maximum
  combined:=.8*lexicalComponent+.2*graphComponent
  candidates[i].result.Ranking=&SearchRankingComponents{Lexical:lexicalComponent,Graph:graphComponent,Combined:combined}
  candidates[i].score=combined*maximum
 }
 return diagnostics,nil
}
type SearchRankingComponents struct {
 Lexical float64 `json:"lexical"`
 Graph float64 `json:"graph"`
 Combined float64 `json:"combined"`
}
